refentry.refsect1:
&reftitle.description;

 public boolYaf_Request_Abstract::isDelete


Verifica se a requisição foi enviada com o método DELETE.

  &reftitle.examples;

   Exemplo de Yaf_Request_Abstract::isDelete


<?php
class CommentController extends Yaf_Controller_Abstract
{
    public function removeAction()
    {
        // Assumindo que a requisição foi enviada com DELETE /comment/remove/id/12
        var_dump($this->getRequest()->isDelete());
    }
}
?>

   &example.outputs.similar;


bool(true)
